import { ChevronDown } from 'lucide-react'
import * as React from 'react'

import { useControllableState } from '~/hooks/use-controllable-state'
import { cx } from '~/lib/cx'
import styles from './collapsible.module.scss'

interface CollapsibleContextValue {
  open: boolean
  setOpen: (open: boolean) => void
  contentId: string
  triggerId: string
}

const CollapsibleContext = React.createContext<CollapsibleContextValue | null>(
  null,
)

function useCollapsible(component: string): CollapsibleContextValue {
  const context = React.useContext(CollapsibleContext)
  if (!context) {
    throw new Error(`<${component}> must be rendered inside <Collapsible>.`)
  }
  return context
}

export interface CollapsibleProps {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  className?: string
  children?: React.ReactNode
}

/** Controlled or uncontrolled disclosure with a smooth height transition. */
export function Collapsible({
  open: controlledOpen,
  defaultOpen = false,
  onOpenChange,
  className,
  children,
}: CollapsibleProps) {
  const [open, setValue] = useControllableState({
    value: controlledOpen,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  })
  const contentId = React.useId()
  const triggerId = React.useId()

  const setOpen = React.useCallback(
    (next: boolean) => setValue(next),
    [setValue],
  )

  const context = React.useMemo<CollapsibleContextValue>(
    () => ({ open, setOpen, contentId, triggerId }),
    [open, setOpen, contentId, triggerId],
  )

  return (
    <CollapsibleContext.Provider value={context}>
      <div
        className={cx(styles.root, className)}
        data-state={open ? 'open' : 'closed'}
      >
        {children}
      </div>
    </CollapsibleContext.Provider>
  )
}

export interface CollapsibleTriggerProps {
  className?: string
  children?: React.ReactNode
}

export function CollapsibleTrigger({
  className,
  children,
}: CollapsibleTriggerProps) {
  const { open, setOpen, contentId, triggerId } =
    useCollapsible('CollapsibleTrigger')

  return (
    <button
      type="button"
      id={triggerId}
      className={cx(styles.trigger, className)}
      aria-expanded={open}
      aria-controls={contentId}
      onClick={() => setOpen(!open)}
    >
      <span className={styles.triggerLabel}>{children}</span>
      <ChevronDown className={styles.chevron} aria-hidden />
    </button>
  )
}

export interface CollapsibleContentProps {
  className?: string
  children?: React.ReactNode
}

export function CollapsibleContent({
  className,
  children,
}: CollapsibleContentProps) {
  const { open, contentId, triggerId } =
    useCollapsible('CollapsibleContent')

  return (
    <div
      id={contentId}
      role="region"
      aria-labelledby={triggerId}
      className={cx(styles.content, className)}
      data-state={open ? 'open' : 'closed'}
      inert={!open || undefined}
    >
      <div className={styles.contentInner}>
        <div className={styles.contentBody}>{children}</div>
      </div>
    </div>
  )
}

@use 'styles' as vz;

.root {
  width: 100%;
}

.trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: vz.space(2);
  width: 100%;
  padding: vz.space(2) vz.space(3);
  border: 0;
  border-radius: vz.radius('lg');
  background: transparent;
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  transition: background-color vz.duration('base') vz.ease('out');

  @include vz.hover {
    background: vz.color('accent');
  }

  @include vz.focus-ring(2px, 2px, 0.6);
}

.trigger-label {
  min-width: 0;
}

.chevron {
  @include vz.icon(4);

  color: vz.color('muted-foreground');
  transition: transform vz.duration('base') vz.ease('out');
}

.trigger[aria-expanded='true'] .chevron {
  transform: rotate(180deg);
}

.content {
  display: grid;
  grid-template-rows: 0fr;
  overflow: hidden;
  opacity: 0;
  transition:
    grid-template-rows vz.duration('base') vz.ease('out'),
    opacity vz.duration('base') vz.ease('out');

  @include vz.motion-reduce {
    transition: none;
  }
}

.content-inner {
  min-height: 0;
}

.content-body {
  padding: vz.space(1) vz.space(3) vz.space(2);
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
  line-height: 1.5;
}

.content[data-state='open'] {
  grid-template-rows: 1fr;
  opacity: 1;
}
